// Situationship: "You're the worker" role. The student is the barista, the waiter, the doctor…
// and the computer is the customer. The conversations are the same as in scenes.js, the other way round:
// the student says the worker's lines (5 turns), and the customer answers with the model answers from scenes.js.
//
// One line per turn:  W(the task, good answers, key words, wrong answer 1, wrong answer 2, flags)  (same format as T in scenes.js)
// For each situation: who the customer is (client, face), what they say when they leave angry (leave),
// and their last line at the end of the conversation (bye, one per level).

function W(task, say, need, w1, w2, flags = ""){ return T("", task, say, need, w1, w2, flags); }

